let source_skeleton_id = native_clip.skeleton.clone().ok_or_else(|| {
    animation_binding_error(
        animation_set_asset,
        &source.asset,
        context,
        "model-bound Animation Set candidates must be bound to an imported skeleton",
    )
})?;
let catalog_source_skeleton = context
    .manifest
    .imported_sub_asset(&source.asset)
    .and_then(|(_, entry, _)| {
        entry
            .import_settings
            .animation_source_skeletons
            .get(source.asset.as_str())
    });
if catalog_source_skeleton.map(String::as_str) != Some(source_skeleton_id.as_str()) {
    return Err(animation_binding_error(
        animation_set_asset,
        &source.asset,
        context,
        format!(
            "model-bound candidate source skeleton metadata is missing or stale (runtime `{}`); reimport the owning source",
            source_skeleton_id.as_str()
        ),
    ));
}

let assets_root = context.asset_root.unwrap_or_else(|| Path::new("."));
